@MainActor func transient_SymbolSolidOval_objectDisplay (
       _ self_x : CanariLength,                          
       _ self_y : CanariLength,                          
       _ self_width : CanariLength,                      
       _ self_height : CanariLength,                     
       _ prefs_symbolColor : NSColor
) -> EBShape {
//--- START OF USER ZONE 2
  let r = NSRect (
    x: self_x,
    y: self_y,
    width: self_width,
    height: self_height
  )
  let bp = BezierPath (ovalIn: r)
  var shape = EBShape ()
  shape.add (filled: [bp], prefs_symbolColor)
  return shape
//--- END OF USER ZONE 2
}

